// Lee el padrón desde Supabase (Core Studio).
// Supabase devuelve un array JSON plano, sin paginación (todos los empleados en una sola llamada).
// Campos nuevos disponibles: probation_end_date, probation_status, manager_email,
// manager_since_date, key_talent, company, termination_date, termination_type.

const vistos = new Set();
const personas = [];

for (const item of $input.all()) {
  const body = item.json;
  // Supabase devuelve array directo (no anidado en .data)
  const lista = Array.isArray(body) ? body : [body];

  for (const e of lista) {
    if (!e || typeof e !== 'object' || !e.id || vistos.has(String(e.id))) continue;
    vistos.add(String(e.id));

    const activo = e.status === 'active';

    personas.push({ json: {
      codigo:           String(e.id),
      nombre:           e.name || 'Sin nombre',
      equipo:           e.dept || 'Sin equipo',
      empresa:          e.company || 'PicallEx',
      lider:            e.manager_email || null,
      fecha_ingreso:    e.hire_date || null,
      fecha_fin_prueba: e.probation_end_date || null,
      estado_prueba:    e.probation_status || null,
      fecha_cambio_lider: e.manager_since_date || null,
      talento_clave:    e.key_talent === true,
      fecha_baja:       e.termination_date || null,
      tipo_baja:        e.termination_type || null,
      activo,
    } });
  }
}

return personas;

// Informe mensual por equipo.
// Se informa el mes anterior y se anticipa el mes que empieza.
// Guarda una "foto" del equipo (solo código, equipo y líder) para comparar el mes siguiente.
// La foto solo se guarda cuando el flujo corre solo (activo), no en las pruebas manuales.

const hoy = $now.startOf('day');
const mesInforme = hoy.minus({ months: 1 });
const inicio = mesInforme.startOf('month'), fin = mesInforme.endOf('month');
const proxInicio = hoy.startOf('month'), proxFin = hoy.endOf('month');
const nombreMes = d => d.setLocale('es').toFormat('LLLL');
const num = x => x.toFixed(1).replace('.', ',');
const entre = (d, a, b) => d && d >= a && d <= b;

const personas = $input.all().map(i => i.json).filter(p => p.activo !== false && p.fecha_ingreso);

const equipos = {};
const eq = n => (equipos[n] ??= { n: 0, ingresos: 0, antig: 0, prueba: 0, finPrueba: 0, aniv: 0, bajas: 0, var: null });

for (const p of personas) {
  const e = eq(p.equipo);
  const ingreso = DateTime.fromISO(String(p.fecha_ingreso).slice(0, 10));
  e.n++;
  e.antig += hoy.diff(ingreso, 'years').years;
  if (entre(ingreso, inicio, fin)) e.ingresos++;
  if (p.fecha_fin_prueba) {
    const fp = DateTime.fromISO(String(p.fecha_fin_prueba).slice(0, 10));
    if (fp >= hoy) e.prueba++;
    if (entre(fp, proxInicio, proxFin)) e.finPrueba++;
  }
  for (const n of [1, 2]) if (entre(ingreso.plus({ years: n }), proxInicio, proxFin)) e.aniv++;
}

// Comparación con la foto del mes anterior
const store = $getWorkflowStaticData('global');
const anterior = store.foto || null;
const actual = Object.fromEntries(personas.map(p => [p.codigo, { equipo: p.equipo, lider: p.lider }]));
let cambiosEquipo = 0, cambiosLider = 0;

if (anterior) {
  const prevPorEquipo = {};
  for (const [cod, a] of Object.entries(anterior)) {
    prevPorEquipo[a.equipo] = (prevPorEquipo[a.equipo] || 0) + 1;
    const b = actual[cod];
    if (!b) eq(a.equipo).bajas++;
    else {
      if (a.equipo !== b.equipo) cambiosEquipo++;
      if (a.lider && b.lider && a.lider !== b.lider) cambiosLider++;
    }
  }
  for (const [nombre, e] of Object.entries(equipos)) e.var = e.n - (prevPorEquipo[nombre] || 0);
}
store.foto = actual;
store.fecha = hoy.toISODate();

// Equipos de menos de 5 personas se agrupan en "Otros equipos", para no exponer a nadie
const MIN_EQUIPO = 5;
const otros = { n: 0, ingresos: 0, antig: 0, prueba: 0, finPrueba: 0, aniv: 0, bajas: 0, var: anterior ? 0 : null, cuantos: 0 };
const visibles = [];
for (const [nombre, e] of Object.entries(equipos)) {
  if (e.n === 0 && e.bajas === 0) continue;
  if (e.n >= MIN_EQUIPO) { visibles.push([nombre, e]); continue; }
  for (const k of ['n', 'ingresos', 'antig', 'prueba', 'finPrueba', 'aniv', 'bajas']) otros[k] += e[k];
  if (anterior && e.var !== null) otros.var += e.var;
  otros.cuantos++;
}
visibles.sort((a, b) => b[1].n - a[1].n);

// Armado del mensaje
const lista = otros.cuantos ? [...visibles, [`Otros equipos (${otros.cuantos} equipos chicos)`, otros]] : visibles;
const tot = lista.reduce((t, [, e]) => ({ n: t.n + e.n, ing: t.ing + e.ingresos, baj: t.baj + e.bajas, ant: t.ant + e.antig }), { n: 0, ing: 0, baj: 0, ant: 0 });
const signo = v => v === null ? '' : v > 0 ? ` (+${v})` : v < 0 ? ` (${v})` : ' (=)';
const plural = (n, s, p) => `${n} ${n === 1 ? s : p}`;

const lineas = lista.map(([nombre, e]) =>
  `• *${nombre}* · ${plural(e.n, 'persona', 'personas')}${signo(e.var)} · ${plural(e.ingresos, 'ingreso', 'ingresos')}` +
  (anterior ? ` · ${plural(e.bajas, 'baja', 'bajas')}` : '') +
  (e.n ? ` · ${num(e.antig / e.n)} años promedio` : '') + (e.prueba ? ` · ${e.prueba} en prueba` : ''));

const proximos = [];
const fp = lista.filter(([, e]) => e.finPrueba).map(([n, e]) => `${n} ${e.finPrueba}`);
const an = lista.filter(([, e]) => e.aniv).map(([n, e]) => `${n} ${e.aniv}`);
if (fp.length) proximos.push(`• Terminan períodos de prueba: ${fp.join(', ')}`);
if (an.length) proximos.push(`• Aniversarios de 1 o 2 años: ${an.join(', ')}`);

let m = `*Lectura de equipos · ${nombreMes(mesInforme)} ${mesInforme.year}*\n_Datos de Core Studio (Supabase) al ${hoy.toFormat('dd/MM')}._\n\n`;
m += `*Total: ${plural(tot.n, 'persona', 'personas')}* · ${plural(tot.ing, 'ingreso', 'ingresos')} en el mes` +
  (anterior ? ` · ${plural(tot.baj, 'baja', 'bajas')}` : '') + ` · ${num(tot.ant / tot.n)} años de antigüedad promedio\n\n`;
m += `*Por equipo*\n${lineas.join('\n')}\n\n`;
if (anterior && (cambiosEquipo || cambiosLider)) {
  m += `*Cambios en la estructura*\n• ${plural(cambiosEquipo, 'persona cambió', 'personas cambiaron')} de equipo · ${plural(cambiosLider, 'persona cambió', 'personas cambiaron')} de líder\n\n`;
}
m += `*Para tener en cuenta en ${nombreMes(hoy)}*\n${proximos.length ? proximos.join('\n') : '• Sin hitos en el mes.'}\n\n`;
m += anterior
  ? '_Tu parte para el Directorio: tres hallazgos y una decisión a pedir._'
  : '_Primer informe: queda como punto de partida. Desde el próximo se suman bajas, variaciones y cambios de estructura._';

return [{ json: { mensaje: m, personas: tot.n } }];

// Resumen del lunes: lo que pasa esta semana y la próxima, ordenado según quién actúa.
// Llega siempre, aunque no haya nada: es la base de la charla de 15 minutos con Zoe.
const MS_DIA = 86400000;
const hoy = Date.parse($now.toISODate());

function sumarMeses(iso, meses) {
  const [y, m, d] = String(iso).slice(0, 10).split('-').map(Number);
  const base = new Date(Date.UTC(y, m - 1 + meses, 1));
  const ultimoDia = new Date(Date.UTC(base.getUTCFullYear(), base.getUTCMonth() + 1, 0)).getUTCDate();
  return Date.UTC(base.getUTCFullYear(), base.getUTCMonth(), Math.min(d, ultimoDia));
}
const fecha = ms => { const d = new Date(ms); return String(d.getUTCDate()).padStart(2, '0') + '/' + String(d.getUTCMonth() + 1).padStart(2, '0'); };

const hitos = [], ingresos = [];
for (const item of $input.all()) {
  const p = item.json;
  if (p.activo === false || !p.fecha_ingreso) continue;
  const ingreso = Date.parse(String(p.fecha_ingreso).slice(0, 10));

  const cand = [1, 2].map(n => ({ fecha: sumarMeses(p.fecha_ingreso, 12 * n), texto: `cumple ${n} ${n === 1 ? 'año' : 'años'}`, quien: 'Zoe', accion: 'charla de crecimiento en la entrevista mensual' }));
  const finPrueba = p.fecha_fin_prueba ? Date.parse(String(p.fecha_fin_prueba).slice(0, 10)) : null;
  if (finPrueba) cand.push({ fecha: finPrueba, texto: 'termina su período de prueba', quien: 'Georgi', accion: 'decidir con el líder si continúa' });

  for (const c of cand) {
    const faltan = Math.round((c.fecha - hoy) / MS_DIA);
    if (faltan >= 0 && faltan <= 13) hitos.push({ ...c, faltan, nombre: p.nombre, equipo: p.equipo });
  }
  const hace = Math.round((hoy - ingreso) / MS_DIA);
  if (hace >= 0 && hace <= 28) ingresos.push({ nombre: p.nombre, equipo: p.equipo, fecha: ingreso });
}

hitos.sort((a, b) => a.faltan - b.faltan || a.nombre.localeCompare(b.nombre));
ingresos.sort((a, b) => b.fecha - a.fecha);
const linea = h => `• ${fecha(h.fecha)} · *${h.nombre}* (${h.equipo}): ${h.texto} → ${h.quien}: ${h.accion}`;
const estaSemana = hitos.filter(h => h.faltan <= 6), proxima = hitos.filter(h => h.faltan >= 7);
const deGeorgi = estaSemana.filter(h => h.quien === 'Georgi').length, deZoe = estaSemana.filter(h => h.quien === 'Zoe').length;

let m = `*Resumen de la semana · ${fecha(hoy)}*\n\n`;
m += `*Esta semana*\n${estaSemana.length ? estaSemana.map(linea).join('\n') : '• Sin hitos.'}\n\n`;
m += `*La semana que viene*\n${proxima.length ? proxima.map(linea).join('\n') : '• Sin hitos.'}\n\n`;
if (ingresos.length) m += `*Ingresos de las últimas 4 semanas* (primer mes: seguimiento cercano)\n${ingresos.map(i => `• *${i.nombre}* (${i.equipo}) · ingresó el ${fecha(i.fecha)}`).join('\n')}\n\n`;
m += `*Para la charla con Zoe*\n` + (estaSemana.length
  ? `${estaSemana.length} ${estaSemana.length === 1 ? 'cosa' : 'cosas'} para esta semana: ${deGeorgi} a cargo de Georgi, ${deZoe} a cargo de Zoe.`
  : 'Semana tranquila: buen momento para adelantar entrevistas mensuales.');
m += `\n\n_Próximamente en este resumen: pedidos de charla de Pulse, alertas y plazos vencidos._`;

return [{ json: { mensaje: m } }];

// Detecta hitos del padrón y arma un solo mensaje.
//
// Cuando lo ejecutás a mano, muestra TODOS los hitos de los próximos 60 días (modo prueba).
// Cuando corre solo, avisa cada hito dos veces: con 21 y con 7 días de anticipación.
const MODO_PRUEBA = typeof $execution !== 'undefined' && $execution.mode !== 'production';

const DIAS_AVISO = [21, 7];
const VENTANA_PRUEBA = 60;
const ANIVERSARIOS = [1, 2]; // años
const MS_DIA = 86400000;

const hoy = Date.parse($now.toISODate());

function sumarMeses(iso, meses) {
  const [y, m, d] = String(iso).slice(0, 10).split('-').map(Number);
  const base = new Date(Date.UTC(y, m - 1 + meses, 1));
  const ultimoDia = new Date(Date.UTC(base.getUTCFullYear(), base.getUTCMonth() + 1, 0)).getUTCDate();
  return Date.UTC(base.getUTCFullYear(), base.getUTCMonth(), Math.min(d, ultimoDia));
}
const fecha = ms => {
  const d = new Date(ms);
  return String(d.getUTCDate()).padStart(2, '0') + '/' + String(d.getUTCMonth() + 1).padStart(2, '0');
};

const hitos = [];
let activos = 0, sinFecha = 0;

for (const item of $input.all()) {
  const p = item.json;
  if (p.activo === false) continue;
  activos++;
  if (!p.fecha_ingreso) { sinFecha++; continue; }

  const candidatos = ANIVERSARIOS.map(n => ({
    fecha: sumarMeses(p.fecha_ingreso, 12 * n),
    texto: `cumple ${n} ${n === 1 ? 'año' : 'años'} en la empresa`,
  }));
  if (p.fecha_fin_prueba) {
    candidatos.push({ fecha: Date.parse(String(p.fecha_fin_prueba).slice(0, 10)), texto: 'termina su período de prueba' });
  }
  if (p.fecha_cambio_lider) {
    candidatos.push({ fecha: Date.parse(String(p.fecha_cambio_lider).slice(0, 10)) + 30 * MS_DIA, texto: 'cumple 30 días con su nuevo líder' });
  }

  for (const c of candidatos) {
    const faltan = Math.round((c.fecha - hoy) / MS_DIA);
    const entra = MODO_PRUEBA ? (faltan >= 0 && faltan <= VENTANA_PRUEBA) : DIAS_AVISO.includes(faltan);
    if (entra) hitos.push({ faltan, fecha: c.fecha, nombre: p.nombre, equipo: p.equipo, clave: p.talento_clave === true, texto: c.texto });
  }
}

hitos.sort((a, b) => a.faltan - b.faltan || a.nombre.localeCompare(b.nombre));
const linea = h => `• ${fecha(h.fecha)} · *${h.nombre}* (${h.equipo})${h.clave ? ' · talento clave' : ''}: ${h.texto}`;

let cuerpo;
if (MODO_PRUEBA) {
  cuerpo = `*Modo prueba · próximos ${VENTANA_PRUEBA} días*\n` + (hitos.length ? hitos.map(linea).join('\n') : 'Sin hitos en el período.') +
    `\n\n_Personas activas leídas: ${activos}. Sin fecha de ingreso: ${sinFecha}._`;
} else {
  if (hitos.length === 0) return [];
  const bloques = [];
  for (const d of [7, 21]) {
    const grupo = hitos.filter(h => h.faltan === d);
    if (grupo.length) bloques.push(`*En ${d} días*\n` + grupo.map(linea).join('\n'));
  }
  cuerpo = bloques.join('\n\n');
}

const mensaje = `*Hitos próximos · Recursos Humanos*\n\n${cuerpo}\n\n_Aviso automático desde Core Studio._`;
return [{ json: { mensaje, cantidad: hitos.length, activos, sin_fecha: sinFecha } }];
